import{_ as t,c as h,o as i,a2 as a}from"./chunks/framework.B7el9cAC.js";const d=JSON.parse('{"title":"Mục 6.6 – Quyền Riêng Tư Số","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-6/6.6-quyen-rieng-tu.md","filePath":"chuong-6/6.6-quyen-rieng-tu.md","lastUpdated":1775336269000}'),g={name:"chuong-6/6.6-quyen-rieng-tu.md"};function o(u,n,c,r,l,e){return i(),h("div",null,[...n[0]||(n[0]=[a(`<h1 id="muc-6-6-–-quyen-rieng-tu-so" tabindex="-1">Mục 6.6 – Quyền Riêng Tư Số <a class="header-anchor" href="#muc-6-6-–-quyen-rieng-tu-so" aria-label="Permalink to &quot;Mục 6.6 – Quyền Riêng Tư Số&quot;">​</a></h1><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><p><strong>Quyền riêng tư có còn tồn tại trong thời đại số không?</strong></p><p>Mỗi ngày bạn:</p><ul><li>Dùng Google Maps → Google biết bạn đang ở đâu</li><li>Tìm kiếm trên Google → Google biết bạn đang nghĩ đến gì</li><li>Lướt Facebook, TikTok → Họ biết bạn thích gì, không thích gì</li><li>Mua hàng online → Họ biết thu nhập ước tính, sở thích mua sắm của bạn</li></ul><p>Thực tế: Bạn đang <strong>trao đổi quyền riêng tư để lấy dịch vụ miễn phí</strong>. Câu nói nổi tiếng trong ngành công nghệ: <em>&quot;Nếu sản phẩm là miễn phí, thì chính bạn là sản phẩm.&quot;</em></p><p>Quyền riêng tư số không có nghĩa là bạn có bí mật xấu cần giấu – mà là quyền <strong>kiểm soát thông tin về bản thân mình</strong>.</p><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="quyen-rieng-tu-so-la-gi" tabindex="-1">Quyền riêng tư số là gì? <a class="header-anchor" href="#quyen-rieng-tu-so-la-gi" aria-label="Permalink to &quot;Quyền riêng tư số là gì?&quot;">​</a></h3><p><strong>Quyền riêng tư số (Digital Privacy)</strong> là quyền của cá nhân trong việc:</p><ul><li><strong>Kiểm soát</strong> thông tin cá nhân trên môi trường số</li><li><strong>Quyết định</strong> ai được thu thập, xem, sử dụng thông tin về mình</li><li><strong>Được bảo vệ</strong> khỏi việc thu thập và sử dụng dữ liệu trái phép</li></ul><h3 id="du-lieu-ca-nhan-personal-data-la-gi" tabindex="-1">Dữ liệu cá nhân (Personal Data) là gì? <a class="header-anchor" href="#du-lieu-ca-nhan-personal-data-la-gi" aria-label="Permalink to &quot;Dữ liệu cá nhân (Personal Data) là gì?&quot;">​</a></h3><p>Dữ liệu cá nhân là mọi thông tin có thể <strong>xác định danh tính</strong> một người:</p><p><strong>Dữ liệu cá nhân cơ bản:</strong></p><ul><li>Họ tên, ngày sinh, giới tính</li><li>Số điện thoại, địa chỉ email</li><li>Địa chỉ nhà, nơi làm việc</li><li>Ảnh chân dung, video</li></ul><p><strong>Dữ liệu cá nhân nhạy cảm:</strong></p><ul><li>Số CMND/CCCD, hộ chiếu</li><li>Thông tin ngân hàng, thẻ tín dụng</li><li>Hồ sơ sức khỏe, bệnh tật</li><li>Quan điểm chính trị, tôn giáo</li><li>Dữ liệu sinh trắc học (vân tay, nhận dạng khuôn mặt)</li></ul><h3 id="cac-moi-đe-doa-đen-quyen-rieng-tu-so" tabindex="-1">Các mối đe dọa đến quyền riêng tư số <a class="header-anchor" href="#cac-moi-đe-doa-đen-quyen-rieng-tu-so" aria-label="Permalink to &quot;Các mối đe dọa đến quyền riêng tư số&quot;">​</a></h3><p><strong>1. Thu thập dữ liệu quá mức (Data Oversharing):</strong></p><ul><li>Ứng dụng yêu cầu quyền truy cập không cần thiết (camera, microphone, danh bạ)</li><li>Cookies theo dõi hành vi lướt web</li><li>Quảng cáo nhắm mục tiêu (targeted advertising)</li></ul><p><strong>2. Rò rỉ dữ liệu (Data Breach):</strong></p><ul><li>Hacker tấn công cơ sở dữ liệu của công ty</li><li>Thông tin cá nhân hàng triệu người bị đánh cắp và bán</li><li>Ví dụ: Rò rỉ dữ liệu Facebook (2021) – 533 triệu tài khoản</li></ul><p><strong>3. Theo dõi trực tuyến (Online Tracking):</strong></p><ul><li>Cookies bên thứ ba theo dõi bạn trên nhiều website</li><li>Pixel theo dõi trong email</li><li>Fingerprinting (nhận dạng thiết bị dù không có cookie)</li></ul><p><strong>4. Khai thác dữ liệu (Data Mining):</strong></p><ul><li>Phân tích hành vi để xây dựng hồ sơ người dùng chi tiết</li><li>Dự đoán hành vi, tâm lý, tài chính từ dữ liệu</li></ul><h3 id="nghi-đinh-13-2023-nđ-cp-–-bao-ve-du-lieu-ca-nhan" tabindex="-1">Nghị định 13/2023/NĐ-CP – Bảo vệ dữ liệu cá nhân <a class="header-anchor" href="#nghi-đinh-13-2023-nđ-cp-–-bao-ve-du-lieu-ca-nhan" aria-label="Permalink to &quot;Nghị định 13/2023/NĐ-CP – Bảo vệ dữ liệu cá nhân&quot;">​</a></h3><p>Nghị định có hiệu lực từ <strong>01/07/2023</strong>, quy định:</p><ul><li><strong>Nguyên tắc:</strong> Thu thập dữ liệu phải có <strong>sự đồng ý</strong> của chủ thể dữ liệu</li><li><strong>Quyền của bạn:</strong> Được biết, được truy cập, được sửa, được xóa dữ liệu của mình</li><li><strong>Nghĩa vụ:</strong> Các tổ chức thu thập dữ liệu phải bảo vệ và không chia sẻ trái phép</li><li><strong>Vi phạm:</strong> Phạt lên đến 5% doanh thu tại Việt Nam</li></ul><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><p><strong>Tại sao quyền riêng tư quan trọng?</strong></p><p>Hãy nghĩ đến <strong>&quot;The Social Dilemma&quot; (Bộ phim tài liệu Netflix, 2020)</strong>:</p><blockquote><p>Mạng xã hội không chỉ thu thập dữ liệu để hiển thị quảng cáo phù hợp. Họ dùng dữ liệu để <strong>dự đoán và thao túng hành vi</strong> của bạn – thời gian sử dụng ứng dụng, quyết định mua hàng, thậm chí quan điểm chính trị.</p></blockquote><p><strong>Vòng lặp dữ liệu:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Bạn dùng ứng dụng → Ứng dụng thu thập dữ liệu</span></span>
<span class="line"><span>→ Phân tích tạo hồ sơ → Hiển thị nội dung cá nhân hóa</span></span>
<span class="line"><span>→ Bạn ở lại ứng dụng lâu hơn → Thu thập thêm dữ liệu</span></span></code></pre></div><p><strong>&quot;Filter Bubble&quot; (Bong bóng lọc):</strong></p><ul><li>Thuật toán chỉ hiển thị những gì bạn &quot;muốn thấy&quot;</li><li>Kết quả: Bạn chỉ tiếp xúc với quan điểm giống mình → cực đoan hóa</li><li>Mỗi người sống trong &quot;thực tế&quot; khác nhau dù dùng cùng internet</li></ul><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="cach-bao-ve-quyen-rieng-tu-so-cua-ban" tabindex="-1">Cách bảo vệ quyền riêng tư số của bạn: <a class="header-anchor" href="#cach-bao-ve-quyen-rieng-tu-so-cua-ban" aria-label="Permalink to &quot;Cách bảo vệ quyền riêng tư số của bạn:&quot;">​</a></h3><p><strong>Trên mạng xã hội:</strong></p><ol><li><strong>Đặt chế độ riêng tư</strong> → Chỉ bạn bè mới xem được bài đăng</li><li><strong>Không đăng thông tin nhạy cảm</strong> → Số CMND, địa chỉ nhà, lịch trình hàng ngày</li><li><strong>Kiểm tra ứng dụng kết nối</strong> → Xóa ứng dụng bên thứ ba không dùng đến</li><li><strong>Xem lại quyền riêng tư</strong> → Định kỳ kiểm tra cài đặt privacy</li></ol><p><strong>Trên thiết bị:</strong></p><ol><li><strong>Cài đặt quyền ứng dụng</strong> → Chỉ cho phép quyền cần thiết (ví dụ: app đèn pin không cần camera)</li><li><strong>Xóa cookie và cache</strong> → Định kỳ làm sạch dữ liệu theo dõi</li><li><strong>Dùng VPN</strong> → Ẩn địa chỉ IP khi dùng WiFi công cộng</li><li><strong>Dùng trình duyệt bảo mật</strong> → Firefox với uBlock Origin, Brave Browser</li></ol><p><strong>Khi đăng ký dịch vụ:</strong></p><ol><li><strong>Đọc điều khoản và chính sách riêng tư</strong> → Xem họ thu thập và dùng gì</li><li><strong>Dùng email phụ</strong> → Cho những dịch vụ không quan trọng</li><li><strong>Không nhập thông tin không cần thiết</strong> → Họ hỏi ngày sinh không có nghĩa bạn phải trả lời thật</li><li><strong>Bỏ chọn quảng cáo</strong> → Tắt tùy chọn chia sẻ dữ liệu cho bên thứ ba</li></ol><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-co-ban-quyen-ung-dung-đien-thoai" tabindex="-1">Ví dụ 1 – Cơ bản: Quyền ứng dụng điện thoại <a class="header-anchor" href="#vi-du-1-–-co-ban-quyen-ung-dung-đien-thoai" aria-label="Permalink to &quot;Ví dụ 1 – Cơ bản: Quyền ứng dụng điện thoại&quot;">​</a></h3><p><strong>Tình huống:</strong> Bạn tải app đèn pin (flashlight) về điện thoại. App yêu cầu quyền truy cập:</p><ul><li>✅ Camera (để bật đèn flash)</li><li>❌ Danh bạ</li><li>❌ Vị trí GPS</li><li>❌ Lịch sử cuộc gọi</li></ul><p><strong>Phân tích:</strong></p><ul><li>Chỉ cần quyền Camera là hợp lý</li><li>Các quyền còn lại: ứng dụng đèn pin <strong>không có lý do gì</strong> cần đến</li><li>Đây là dấu hiệu ứng dụng đang <strong>thu thập dữ liệu trái mục đích</strong></li></ul><p><strong>Hành động đúng:</strong> Từ chối các quyền không cần thiết hoặc gỡ cài đặt ứng dụng này.</p><hr><h3 id="vi-du-2-–-thuc-te-ro-ri-du-lieu-facebook-2021" tabindex="-1">Ví dụ 2 – Thực tế: Rò rỉ dữ liệu Facebook 2021 <a class="header-anchor" href="#vi-du-2-–-thuc-te-ro-ri-du-lieu-facebook-2021" aria-label="Permalink to &quot;Ví dụ 2 – Thực tế: Rò rỉ dữ liệu Facebook 2021&quot;">​</a></h3><p><strong>Sự kiện thực tế:</strong> Tháng 4/2021, dữ liệu của <strong>533 triệu người dùng Facebook</strong> từ 106 quốc gia bị đăng công khai trên mạng, bao gồm:</p><ul><li>Số điện thoại</li><li>Tên đầy đủ</li><li>Địa chỉ email</li><li>Ngày sinh</li><li>Nơi làm việc</li></ul><p><strong>Ảnh hưởng:</strong></p><ul><li>Dữ liệu này được dùng để <strong>tấn công giả mạo (phishing)</strong>, <strong>lừa đảo qua điện thoại (vishing)</strong></li><li>Người dùng VN cũng bị ảnh hưởng</li></ul><p><strong>Bài học:</strong> Ngay cả khi bạn không đăng thông tin công khai, nền tảng vẫn có thể bị hack và thông tin của bạn bị lộ. Hãy hạn chế thông tin cung cấp cho các nền tảng.</p><hr><h3 id="vi-du-3-–-nang-cao-quang-cao-lang-nghe-–-thuc-te-hay-huyen-thoai" tabindex="-1">Ví dụ 3 – Nâng cao: &quot;Quảng cáo lắng nghe&quot; – Thực tế hay huyền thoại? <a class="header-anchor" href="#vi-du-3-–-nang-cao-quang-cao-lang-nghe-–-thuc-te-hay-huyen-thoai" aria-label="Permalink to &quot;Ví dụ 3 – Nâng cao: &quot;Quảng cáo lắng nghe&quot; – Thực tế hay huyền thoại?&quot;">​</a></h3><p><strong>Tình huống phổ biến:</strong> Bạn nói chuyện với bạn về giày thể thao. 10 phút sau, Instagram hiển thị quảng cáo giày thể thao. Có phải điện thoại đang &quot;nghe lén&quot;?</p><p><strong>Phân tích khoa học:</strong></p><ul><li>Về mặt kỹ thuật: Bật microphone liên tục và phân tích real-time tiêu tốn pin và băng thông khổng lồ – <strong>rất khó làm mà không ai biết</strong></li><li>Thực tế: Thuật toán không cần nghe – họ biết bạn quan tâm đến giày vì bạn vừa tìm kiếm, vừa xem video giày, bạn bè của bạn đang mua giày...</li><li><strong>Kết luận:</strong> Không phải &quot;nghe lén&quot; – mà là thuật toán dự đoán đủ chính xác đến mức cảm giác như bị nghe.</li></ul><p><strong>Điều đáng lo hơn:</strong> Không phải microphone – mà là <strong>bao nhiêu dữ liệu về bạn</strong> mà thuật toán đã có để dự đoán chính xác như vậy.</p><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="so-sanh-cac-muc-đo-rieng-tu-tren-mang-xa-hoi" tabindex="-1">So sánh các mức độ riêng tư trên mạng xã hội <a class="header-anchor" href="#so-sanh-cac-muc-đo-rieng-tu-tren-mang-xa-hoi" aria-label="Permalink to &quot;So sánh các mức độ riêng tư trên mạng xã hội&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Cài đặt</th><th>Ai xem được</th><th>Rủi ro</th></tr></thead><tbody><tr><td>Công khai (Public)</td><td>Tất cả mọi người</td><td>Cao – người lạ, nhà tuyển dụng, hacker</td></tr><tr><td>Bạn bè (Friends)</td><td>Chỉ người bạn kết nối</td><td>Trung bình</td></tr><tr><td>Bạn bè của bạn bè</td><td>Mở rộng không kiểm soát</td><td>Cao hơn dự kiến</td></tr><tr><td>Chỉ mình tôi (Only me)</td><td>Chỉ bạn</td><td>Thấp nhất</td></tr></tbody></table><h3 id="so-sanh-cac-cong-cu-bao-ve-quyen-rieng-tu" tabindex="-1">So sánh các công cụ bảo vệ quyền riêng tư <a class="header-anchor" href="#so-sanh-cac-cong-cu-bao-ve-quyen-rieng-tu" aria-label="Permalink to &quot;So sánh các công cụ bảo vệ quyền riêng tư&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Công cụ</th><th>Bảo vệ khỏi gì</th><th>Hạn chế</th></tr></thead><tbody><tr><td><strong>VPN</strong></td><td>Che IP với website, ISP</td><td>Không ẩn khỏi nền tảng mạng xã hội</td></tr><tr><td><strong>Trình duyệt ẩn danh</strong></td><td>Cookie phiên, lịch sử trình duyệt</td><td>Không ẩn IP; ISP vẫn thấy</td></tr><tr><td><strong>uBlock Origin</strong></td><td>Quảng cáo, tracker</td><td>Cần cài thêm extension</td></tr><tr><td><strong>Cài đặt riêng tư mạng xã hội</strong></td><td>Người lạ xem hồ sơ</td><td>Nền tảng vẫn thu thập dữ liệu của bạn</td></tr><tr><td><strong>Dùng ít mạng xã hội</strong></td><td>Thu thập dữ liệu tổng thể</td><td>Mất kết nối xã hội</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>✅ <strong>Quyền riêng tư số</strong> = quyền kiểm soát thông tin cá nhân trên môi trường số</li><li>✅ <strong>Dữ liệu cá nhân</strong> = mọi thông tin có thể xác định danh tính một người</li><li>✅ <strong>Dữ liệu nhạy cảm</strong> = CMND, sức khỏe, ngân hàng, sinh trắc học</li><li>✅ <strong>Data Breach</strong> = rò rỉ dữ liệu do bị hack</li><li>✅ <strong>Nghị định 13/2023</strong> = bảo vệ dữ liệu cá nhân tại VN, hiệu lực 01/07/2023</li><li>✅ <strong>Filter Bubble</strong> = bong bóng thông tin, thuật toán chỉ cho bạn xem những gì bạn thích</li><li>✅ <em>&quot;Nếu sản phẩm miễn phí, bạn là sản phẩm&quot;</em> – dịch vụ miễn phí thường đổi bằng dữ liệu</li><li>✅ Bảo vệ: <strong>Đặt chế độ riêng tư + Kiểm tra quyền app + Không đăng thông tin nhạy cảm</strong></li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><h3 id="cau-1-de-du-lieu-ca-nhan-nhay-cam-bao-gom-nhung-loai-thong-tin-nao" tabindex="-1">Câu 1 (Dễ): &quot;Dữ liệu cá nhân nhạy cảm&quot; bao gồm những loại thông tin nào? <a class="header-anchor" href="#cau-1-de-du-lieu-ca-nhan-nhay-cam-bao-gom-nhung-loai-thong-tin-nao" aria-label="Permalink to &quot;Câu 1 (Dễ): &quot;Dữ liệu cá nhân nhạy cảm&quot; bao gồm những loại thông tin nào?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Dữ liệu cá nhân nhạy cảm bao gồm: số CMND/CCCD/hộ chiếu, thông tin ngân hàng và thẻ tín dụng, hồ sơ sức khỏe và bệnh tật, quan điểm chính trị và tôn giáo, dữ liệu sinh trắc học (vân tay, nhận dạng khuôn mặt, võng mạc).</p></blockquote><hr><h3 id="cau-2-de-cau-noi-nao-sau-đay-mo-ta-đung-nhat-ve-mo-hinh-kinh-doanh-cua-mang-xa-hoi-mien-phi" tabindex="-1">Câu 2 (Dễ): Câu nói nào sau đây mô tả đúng nhất về mô hình kinh doanh của mạng xã hội miễn phí? <a class="header-anchor" href="#cau-2-de-cau-noi-nao-sau-đay-mo-ta-đung-nhat-ve-mo-hinh-kinh-doanh-cua-mang-xa-hoi-mien-phi" aria-label="Permalink to &quot;Câu 2 (Dễ): Câu nói nào sau đây mô tả đúng nhất về mô hình kinh doanh của mạng xã hội miễn phí?&quot;">​</a></h3><p><strong>A.</strong> &quot;Dịch vụ miễn phí vì nhà sản xuất rất giàu và muốn giúp đỡ&quot;<br><strong>B.</strong> &quot;Dịch vụ miễn phí vì được Chính phủ tài trợ&quot;<br><strong>C.</strong> &quot;Nếu sản phẩm là miễn phí, thì bạn là sản phẩm&quot;<br><strong>D.</strong> &quot;Dịch vụ miễn phí chỉ để thu hút người dùng, sau này sẽ tính phí&quot;</p><blockquote><p><strong>Đáp án: C</strong> – Mạng xã hội miễn phí kiếm tiền bằng cách thu thập dữ liệu người dùng và bán quảng cáo nhắm mục tiêu. Dữ liệu hành vi của bạn là &quot;hàng hóa&quot; của họ.</p></blockquote><hr><h3 id="cau-3-trung-binh-giai-thich-filter-bubble-bong-bong-loc-la-gi-va-tac-hai-cua-no" tabindex="-1">Câu 3 (Trung bình): Giải thích &quot;Filter Bubble&quot; (bong bóng lọc) là gì và tác hại của nó? <a class="header-anchor" href="#cau-3-trung-binh-giai-thich-filter-bubble-bong-bong-loc-la-gi-va-tac-hai-cua-no" aria-label="Permalink to &quot;Câu 3 (Trung bình): Giải thích &quot;Filter Bubble&quot; (bong bóng lọc) là gì và tác hại của nó?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Filter Bubble là hiện tượng thuật toán mạng xã hội chỉ hiển thị những nội dung phù hợp với sở thích, quan điểm của người dùng (dựa trên dữ liệu hành vi), tạo ra &quot;bong bóng&quot; thông tin cá nhân hóa.</p><p><strong>Tác hại:</strong> (1) Người dùng chỉ tiếp xúc với ý kiến giống mình → không thấy quan điểm đa chiều; (2) Có thể dẫn đến cực đoan hóa quan điểm; (3) Tin tức sai lệch phù hợp với &quot;bong bóng&quot; dễ được tin hơn; (4) Chia rẽ xã hội vì mỗi người sống trong &quot;thực tế thông tin&quot; khác nhau.</p></blockquote><hr><h3 id="cau-4-trung-binh-ban-tai-mot-ung-dung-game-mien-phi-khi-cai-đat-no-yeu-cau-quyen-truy-cap-danh-ba-vi-tri-gps-va-microphone-ban-nen-lam-gi" tabindex="-1">Câu 4 (Trung bình): Bạn tải một ứng dụng game miễn phí. Khi cài đặt, nó yêu cầu quyền truy cập danh bạ, vị trí GPS, và microphone. Bạn nên làm gì? <a class="header-anchor" href="#cau-4-trung-binh-ban-tai-mot-ung-dung-game-mien-phi-khi-cai-đat-no-yeu-cau-quyen-truy-cap-danh-ba-vi-tri-gps-va-microphone-ban-nen-lam-gi" aria-label="Permalink to &quot;Câu 4 (Trung bình): Bạn tải một ứng dụng game miễn phí. Khi cài đặt, nó yêu cầu quyền truy cập danh bạ, vị trí GPS, và microphone. Bạn nên làm gì?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> (1) <strong>Đánh giá tính hợp lý</strong> – game có cần danh bạ, GPS, microphone để hoạt động không? Thường là không; (2) <strong>Từ chối các quyền không cần thiết</strong> – chỉ cấp quyền thực sự cần thiết cho chức năng của game; (3) <strong>Tìm hiểu lý do</strong> – đọc chính sách riêng tư để hiểu họ thu thập dữ liệu này để làm gì; (4) <strong>Gỡ cài đặt</strong> nếu ứng dụng không hoạt động khi từ chối quyền bất hợp lý; (5) <strong>Báo cáo</strong> lên Google Play/App Store nếu ứng dụng ép buộc quyền truy cập không liên quan.</p></blockquote><hr><h3 id="cau-5-van-dung-phan-tich-toi-khong-co-gi-đe-giau-nen-toi-khong-can-quan-tam-đen-quyen-rieng-tu-quan-điem-nay-đung-hay-sai-tai-sao" tabindex="-1">Câu 5 (Vận dụng): Phân tích: &quot;Tôi không có gì để giấu, nên tôi không cần quan tâm đến quyền riêng tư.&quot; Quan điểm này đúng hay sai? Tại sao? <a class="header-anchor" href="#cau-5-van-dung-phan-tich-toi-khong-co-gi-đe-giau-nen-toi-khong-can-quan-tam-đen-quyen-rieng-tu-quan-điem-nay-đung-hay-sai-tai-sao" aria-label="Permalink to &quot;Câu 5 (Vận dụng): Phân tích: &quot;Tôi không có gì để giấu, nên tôi không cần quan tâm đến quyền riêng tư.&quot; Quan điểm này đúng hay sai? Tại sao?&quot;">​</a></h3><blockquote><p><strong>Đáp án:</strong> Quan điểm này <strong>sai</strong> vì nhiều lý do:</p><ol><li><strong>Quyền riêng tư không phải chỉ để giấu bí mật xấu</strong> – mà là quyền kiểm soát thông tin về bản thân. Bạn không giấu gì nhưng bạn vẫn có quyền không cho người lạ vào nhà.</li><li><strong>Dữ liệu bị lạm dụng theo nhiều cách:</strong> Thông tin vô hại hôm nay có thể gây hại khi kết hợp với thông tin khác (ví dụ: lịch trình hàng ngày + địa chỉ nhà = nguy hiểm nếu bị kẻ xấu biết).</li><li><strong>Thay đổi theo bối cảnh:</strong> Điều &quot;không ngại&quot; hôm nay có thể gây hại trong tương lai (ảnh thời thơ ấu đăng public có thể ảnh hưởng khi xin việc sau này).</li><li><strong>Dữ liệu = quyền lực:</strong> Ai nắm dữ liệu của bạn có thể ảnh hưởng đến quyết định, hành vi của bạn thông qua quảng cáo và nội dung cá nhân hóa.</li></ol></blockquote><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Quan niệm sai</th><th>Thực tế đúng</th></tr></thead><tbody><tr><td>&quot;Chế độ ẩn danh (incognito) giúp ẩn hoàn toàn&quot;</td><td>Ẩn danh chỉ xóa lịch sử trình duyệt cục bộ; ISP, trường học, công ty vẫn thấy</td></tr><tr><td>&quot;Chỉ có hacker mới quan tâm đến dữ liệu của mình&quot;</td><td>Quảng cáo, bảo hiểm, tuyển dụng... đều có thể dùng dữ liệu của bạn</td></tr><tr><td>&quot;Đọc điều khoản sử dụng không quan trọng&quot;</td><td>Điều khoản cho thấy họ thu thập gì và dùng ra sao</td></tr><tr><td>&quot;Chỉ kẻ xấu mới cần quyền riêng tư&quot;</td><td>Quyền riêng tư là quyền cơ bản của con người, không liên quan đến mục đích xấu</td></tr><tr><td>&quot;Xóa tài khoản là đủ để xóa dữ liệu&quot;</td><td>Nhiều nền tảng giữ lại dữ liệu sau khi xóa tài khoản; phải yêu cầu xóa dữ liệu riêng</td></tr><tr><td>&quot;VPN giúp ẩn danh hoàn toàn&quot;</td><td>VPN chỉ ẩn IP với website; nhà cung cấp VPN vẫn thấy traffic của bạn</td></tr></tbody></table>`,99)])])}const b=t(g,[["render",o]]);export{d as __pageData,b as default};
